#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_rtio.h>
#include <zephyr/rtio/rtio.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(i2c_rtio, CONFIG_I2C_RTIO_LOG_LEVEL);

static void i2c_iodev_submit_work_handler(struct k_work *work);

struct i2c_rtio_work {
	struct k_work work;
	struct rtio_iodev_sqe *sqe;
	const struct device *dev;
	struct i2c_msg *msgs;
	uint8_t *read_buf;
	size_t read_len;
	int msg_count;
};

K_WORK_DEFINE_STATIC(i2c_rtio_work_item, i2c_iodev_submit_work_handler);

static void i2c_iodev_submit_work_handler(struct k_work *work)
{
	struct i2c_rtio_work *rtio_work = CONTAINER_OF(work, struct i2c_rtio_work, work);
	const struct device *dev = rtio_work->dev;
	struct rtio_iodev_sqe *sqe = rtio_work->sqe;
	struct i2c_msg *msgs = rtio_work->msgs;
	uint8_t *read_buf = rtio_work->read_buf;
	size_t read_len = rtio_work->read_len;
	int msg_count = rtio_work->msg_count;
	int ret;

	LOG_DBG("Sync RTIO work item for: %p", sqe);

	ret = i2c_transfer(dev, msgs, msg_count, RTIO_IODEV_SQE_GET_ADDR(sqe));

	if (ret == 0 && read_buf != NULL) {
		/* Copy data from temporary buffer to user buffer */
		rtio_sbuf_copy_to_user(sqe, read_buf, read_len);
	}

	/* Free temporary messages and read buffer */
	if (msgs != NULL) {
		rtio_sbuf_free(sqe, msgs);
	}
	if (read_buf != NULL) {
		rtio_sbuf_free(sqe, read_buf);
	}

	rtio_iodev_sqe_complete(sqe, ret);
}

static int i2c_iodev_submit_fallback(const struct device *dev, struct rtio_iodev_sqe *sqe)
{
	const struct i2c_rtio_iodev_data *data = sqe->iodev_data;
	struct i2c_msg *msgs;
	uint8_t *read_buf = NULL;
	size_t read_len = 0;
	int i;

	LOG_DBG("Executing fallback for dev: %p, sqe: %p", dev, sqe);

	/* Allocate temporary messages array */
	msgs = rtio_sbuf_alloc(sqe, sizeof(struct i2c_msg) * data->msg_count);
	if (msgs == NULL) {
		LOG_ERR("Failed to allocate I2C messages buffer");
		return -ENOMEM; /* Fix: Return error if allocation fails */
	}

	/* Copy messages from user to temporary buffer and identify total read length */
	for (i = 0; i < data->msg_count; i++) {
		msgs[i] = data->msgs[i];
		if ((msgs[i].flags & I2C_MSG_RW_MASK) == I2C_MSG_READ) {
			read_len += msgs[i].len;
		}
	}

	if (read_len > 0) {
		read_buf = rtio_sbuf_alloc(sqe, read_len);
		if (read_buf == NULL) {
			LOG_ERR("Failed to allocate I2C read buffer");
			rtio_sbuf_free(sqe, msgs); /* Fix: Free previously allocated msgs */
			return -ENOMEM; /* Fix: Return error if allocation fails */
		}

		/* Update read message buffers to point to the temporary read_buf */
		size_t current_offset = 0;
		for (i = 0; i < data->msg_count; i++) {
			if ((msgs[i].flags & I2C_MSG_RW_MASK) == I2C_MSG_READ) {
				msgs[i].buf = read_buf + current_offset;
				current_offset += msgs[i].len;
			}
		}
	}

	/* Schedule work item for synchronous transfer */
	struct i2c_rtio_work *rtio_work = &i2c_rtio_work_item;
	rtio_work->dev = dev;
	rtio_work->sqe = sqe;
	rtio_work->msgs = msgs;
	rtio_work->read_buf = read_buf;
	rtio_work->read_len = read_len;
	rtio_work->msg_count = data->msg_count;

	k_work_submit(&rtio_work->work);

	return 0;
}

static const struct rtio_iodev_api i2c_rtio_iodev_api = {
	.submit = i2c_iodev_submit_fallback,
};

void i2c_rtio_iodev_init(struct rtio_iodev_sqe *sqe, const struct device *dev,
			 const struct i2c_rtio_iodev_data *data)
{
	sqe->iodev_data = data;
	sqe->iodev_api = &i2c_rtio_iodev_api;
	sqe->dev = dev;
}
